enum WindowClass { compact, medium, expanded }

// Decide the form factor ONCE, above the widgets that own state
class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final windowClass = switch (MediaQuery.sizeOf(context).width) {
      >= 840 => WindowClass.expanded,
      >= 600 => WindowClass.medium,
      _ => WindowClass.compact,
    };
    // FeedList is the same element in all three chromes, so its scroll survives
    return HomeChrome(windowClass: windowClass, child: const FeedList());
  }
}

