// A component decides from the box it is given, never from the window
class ProductCard extends StatelessWidget {
  const ProductCard({super.key, required this.product});

  final Product product;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        // component breakpoint: "do two columns fit HERE", not "is this a tablet"
        final twoColumn = constraints.maxWidth >= 480;
        final image = Image.network(product.image, fit: BoxFit.cover);
        final text = ProductSummary(product: product);

        return twoColumn
            ? Row(children: [SizedBox(width: 200, child: image), Expanded(child: text)])
            : Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [image, text],
              );
      },
    );
  }
}

