class _InboxScreenState extends State<InboxScreen> {
  String? _selectedId;  // selection lives ABOVE the breakpoint

  void _select(String? id) => setState(() => _selectedId = id);

  @override
  Widget build(BuildContext context) {
    final twoPane = MediaQuery.sizeOf(context).width >= 840;

    if (twoPane) {
      return PopScope(
        canPop: _selectedId == null,  // back clears the pane, not the screen
        onPopInvokedWithResult: (didPop, _) {
          if (!didPop) _select(null);
        },
        child: Row(
          children: [
            Expanded(flex: 2, child: MailList(selectedId: _selectedId, onSelect: _select)),
            const VerticalDivider(width: 1),
            Expanded(
              flex: 3,
              child: _selectedId == null
                  ? const EmptyDetail()
                  : MailDetail(key: ValueKey(_selectedId), id: _selectedId!),
            ),
          ],
        ),
      );
    }

    // Declarative stack: the detail route EXISTS only while there is no pane for it
    return Navigator(
      pages: [
        MaterialPage(key: const ValueKey('list'), child: MailList(onSelect: _select)),
        if (_selectedId != null)
          MaterialPage(key: ValueKey(_selectedId), child: MailDetail(id: _selectedId!)),
      ],
      onDidRemovePage: (page) => _select(null),  // replaces the deprecated onPopPage
    );
  }
}

// one source of destinations: the index must mean the same thing in every chrome
const destinations = [
  (icon: Icons.inbox, label: 'Inbox'),
  (icon: Icons.send, label: 'Sent'),
];

// shell is go_router's StatefulNavigationShell: one Navigator per destination
Widget adaptiveShell(BuildContext context, StatefulNavigationShell shell) {
  final width = MediaQuery.sizeOf(context).width;
  final Widget body = shell;  // ONE child, reused by every chrome

  if (width >= 1200) {
    return Scaffold(
      body: Row(children: [
        NavigationDrawer(  // placed in a Row it is permanent, not modal
          selectedIndex: shell.currentIndex,
          onDestinationSelected: shell.goBranch,
          children: [
            for (final d in destinations)
              NavigationDrawerDestination(icon: Icon(d.icon), label: Text(d.label)),
          ],
        ),
        Expanded(child: body),
      ]),
    );
  }

  if (width >= 600) {
    final extended = width >= 840;
    return Scaffold(
      body: Row(children: [
        NavigationRail(
          extended: extended,
          // asserted: an extended rail must not also draw its own labels
          labelType: extended
              ? NavigationRailLabelType.none
              : NavigationRailLabelType.selected,
          selectedIndex: shell.currentIndex,
          onDestinationSelected: shell.goBranch,
          destinations: [
            for (final d in destinations)
              NavigationRailDestination(icon: Icon(d.icon), label: Text(d.label)),
          ],
        ),
        Expanded(child: body),
      ]),
    );
  }

  return Scaffold(
    body: body,
    bottomNavigationBar: NavigationBar(  // the Material 3 bottom bar
      selectedIndex: shell.currentIndex,
      onDestinationSelected: shell.goBranch,
      destinations: [
        for (final d in destinations)
          NavigationDestination(icon: Icon(d.icon), label: d.label),
      ],
    ),
  );
}

