class HingeAwarePanes extends StatelessWidget {
  const HingeAwarePanes({super.key, required this.left, required this.right});

  final Widget left;
  final Widget right;

  @override
  Widget build(BuildContext context) {
    final features = MediaQuery.displayFeaturesOf(context)
        .where((f) => f.type != DisplayFeatureType.cutout)
        .toList();
    final width = MediaQuery.sizeOf(context).width;

    // a zero-width fold is a crease on one continuous screen — draw across it
    final blocking = features.where((f) => f.bounds.width > 0).toList();
    if (blocking.isEmpty) {
      return Row(children: [Expanded(child: left), Expanded(child: right)]);
    }

    final f = blocking.first;
    if (f.bounds.width >= f.bounds.height) {
      return Column(children: [Expanded(child: left), Expanded(child: right)]);
    }

    return Row(children: [
      SizedBox(width: f.bounds.left, child: left),
      SizedBox(width: f.bounds.width),  // nothing lives under the hinge
      SizedBox(width: width - f.bounds.right, child: right),
    ]);
  }
}

