const _sizes = <String, Size>{
  'phone': Size(390, 844),
  'foldable': Size(673, 841),
  'tablet': Size(1024, 768),
  'desktop': Size(1440, 900),
};

Future<void> pumpAt(WidgetTester tester, Size size, double scale, Widget child) async {
  tester.view.devicePixelRatio = 3.0;
  tester.view.physicalSize = size * 3.0;
  addTearDown(tester.view.reset);   // never leak the surface into the next test
  await tester.pumpWidget(
    MaterialApp(
      home: MediaQuery(
        data: MediaQueryData(
          size: size,
          textScaler: TextScaler.linear(scale),   // textScaleFactor is deprecated
        ),
        child: child,
      ),
    ),
  );
}

void main() {
  // 4 sizes x 2 scales = 8 checks, 0 golden files
  for (final entry in _sizes.entries) {
    for (final scale in const [1.0, 2.0]) {
      testWidgets('${entry.key} at ${scale}x lays out', (tester) async {
        await pumpAt(tester, entry.value, scale, const OrderScreen());
        expect(tester.takeException(), isNull);  // a RenderFlex overflow lands here
        final wide = entry.value.width >= 840;
        expect(find.byType(NavigationRail), wide ? findsOneWidget : findsNothing);
      });
    }
  }

  // ONE golden for the component, three widths inside the picture
  testWidgets('OrderCard across widths', (tester) async {
    await pumpAt(tester, const Size(400, 900), 1.0, const Column(
      children: [
        SizedBox(width: 320, child: OrderCard()),
        SizedBox(width: 240, child: OrderCard()),
        SizedBox(width: 160, child: OrderCard()),
      ],
    ));
    await expectLater(
        find.byType(Column), matchesGoldenFile('goldens/order_card.png'));
  });
}

class _OrdersRouteState extends State<OrdersRoute> {
  // Owned ABOVE the layout branch — a resize cannot dispose these
  String? _selectedId;
  bool _wide = false;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, c) {
        // Hysteresis: 840 going wide, 800 coming back, so the edge cannot
        // flip-flop. Idempotent — the same width always gives the same answer.
        _wide = _wide ? c.maxWidth >= 800 : c.maxWidth >= 840;

        final list = OrderList(
          key: const PageStorageKey('orders'),   // offset survives the swap
          selectedId: _selectedId,
          onSelect: (id) => setState(() => _selectedId = id),
        );

        if (!_wide) {
          return _selectedId == null ? list : OrderDetail(id: _selectedId);
        }
        return Row(
          children: [
            SizedBox(width: 320, child: list),
            const VerticalDivider(width: 1),
            Expanded(child: OrderDetail(id: _selectedId)),
          ],
        );
      },
    );
  }
}

