enum WindowClass { compact, medium, expanded, large }

WindowClass classify(double width) => switch (width) {
      < 600 => WindowClass.compact,
      < 840 => WindowClass.medium,
      < 1200 => WindowClass.expanded,
      _ => WindowClass.large,
    };

// The ONLY widget on this screen that knows a width exists
class InboxScreen extends StatelessWidget {
  const InboxScreen({super.key, required this.state});
  final InboxState state;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, c) => switch (classify(c.maxWidth)) {
        WindowClass.compact => _CompactInbox(state: state),
        WindowClass.medium || WindowClass.expanded => _SplitInbox(state: state),
        WindowClass.large => _SplitInbox(state: state, showPreview: true),
      },
    );
  }
}

